424:     const ux = vx / length, uy = vy / length;
425:     const px = (car.x - car.y) * 32 - uy * 4.8;
426:     const py = (car.x + car.y) * 16 + ux * 4.8;
427:     const halfLength = car.type === 'bus' || car.type === 'truck' ? 16 : car.type === 'motorcycle' ? 6.5 : 10;
428:     return { x: px, y: py, ux, uy, halfLength, halfWidth: 4.6 };
429:   }
430:   function carsOverlap(a, b) {
431:     const sa = carShape(a), sb = carShape(b);
432:     const axes = [[sa.ux, sa.uy], [-sa.uy, sa.ux], [sb.ux, sb.uy], [-sb.uy, sb.ux]];
433:     for (const [ax, ay] of axes) {
434:       const distance = Math.abs((sb.x - sa.x) * ax + (sb.y - sa.y) * ay);
435:       const ra = sa.halfLength * Math.abs(sa.ux * ax + sa.uy * ay) + sa.halfWidth * Math.abs(-sa.uy * ax + sa.ux * ay);
436:       const rb = sb.halfLength * Math.abs(sb.ux * ax + sb.uy * ay) + sb.halfWidth * Math.abs(-sb.uy * ax + sb.ux * ay);
437:       if (distance >= ra + rb) return false;
438:     }
439:     return true;
440:   }
441:   function nextCarState(car, dt, size, isRoad) {
442:     const next = { ...car };
443:     next.t += dt * next.speed;
444:     if (next.t >= 1) {
445:       const tx = Math.round(next.toX - .5), ty = Math.round(next.toY - .5);
446:       const prevDx = Math.sign(next.toX - next.fromX), prevDy = Math.sign(next.toY - next.fromY);
447:       next.fromX = next.toX; next.fromY = next.toY;
448:       const choices = [];
449:       for (const [dx, dy] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
450:         const nx = tx + dx, ny = ty + dy;
451:         if (nx >= 0 && ny >= 0 && nx < size && ny < size && isRoad(nx, ny)) choices.push({ x: nx, y: ny, dx, dy });
452:       }
453:       if (!choices.length) { next.alive = false; return next; }
454:       const reverse = { dx: -prevDx, dy: -prevDy };
455:       const forward = choices.filter(pick => pick.dx !== reverse.dx || pick.dy !== reverse.dy);
456:       const options = forward.length ? forward : choices;
457:       const pick = options[Math.floor(Math.random() * options.length)];
458:       next.toX = pick.x + .5; next.toY = pick.y + .5;
459:       next.dir = pick.dx > 0 ? 'x' : pick.dx < 0 ? '-x' : pick.dy > 0 ? 'y' : '-y';
460:       next.t = 0;
461:     }
462:     next.x = lerp(next.fromX, next.toX, next.t);
463:     next.y = lerp(next.fromY, next.toY, next.t);
464:     return next;
465:   }
466:   function spawnCars(initial) {
467:     const roads = allRoads();
468:     if (!roads.length) return;
469:     const cap = Math.min(16, Math.floor(roads.length / 2.4));
470:     let attempts = 0;
471:     while (state.cars.length < cap && attempts++ < cap * 24) {
472:       const r = roads[Math.floor(Math.random() * roads.length)];
473:       const c = newCar(r.x, r.y);
474:       if (!c) continue;
475:       c.t = initial ? Math.random() : 0;
476:       c.x = lerp(c.fromX, c.toX, c.t); c.y = lerp(c.fromY, c.toY, c.t);
477:       if (state.cars.some(other => carsOverlap(c, other))) continue;
478:       state.cars.push(c);
479:     }
480:   }
481:   function ensureCars() { spawnCars(); }
482:   function updateCars(dt) {
483:     if (!state || !state.cars) return;
484:     const isRoad = (x, y) => state.grid[idx(x, y)].road;
485:     for (const c of state.cars) {
486:       if (!c.alive) continue;
487:       const next = nextCarState(c, dt, state.gridSize, isRoad);
488:       if (state.cars.some(other => other !== c && carsOverlap(next, other))) continue;
489:       Object.assign(c, next);
490:     }
491:     state.cars = state.cars.filter(c => c.alive);
492:     const roads = allRoads();
493:     if (state.cars.length < Math.min(14, Math.floor(roads.length / 2.4)) && Math.random() < .02) {
494:       const r = roads[Math.floor(Math.random() * roads.length)];
495:       if (r) {
496:         const c = newCar(r.x, r.y);
497:         if (c && !state.cars.some(other => carsOverlap(c, other))) state.cars.push(c);
498:       }
499:     }
500:   }
