529:   function recalc() {
530:     if (!state) return;
531:     let pop = 0, workers = 0, jobs = 0, cJobs = 0, iJobs = 0;
532:     let powerUse = 0, powerCap = 0, waterUse = 0, waterCap = 0, expense = 0;
533:     let roadCount = 0, zoneCount = 0, houses = 0, shops = 0, factories = 0;
534:     let hasPower = false, hasWater = false, hasPark = false, hasSchool = false, hasStadium = false;
535:     const houseList = [], amenities = [], polluters = [];
536:     for (const b of state.buildings) {
537:       const d = defOf(b); if (!d) continue;
538:       expense += d.maint || 0;
539:       if (d.kind === 'zone-r') {
540:         zoneCount++;
541:         if (b.level > 0) {
542:           pop += levelVal(d, 'cap', b.level);
543:           powerUse += levelVal(d, 'powerUse', b.level);
544:           waterUse += levelVal(d, 'waterUse', b.level);
545:           houseList.push(b); houses++;
546:         }
547:       } else if (d.kind === 'zone-c') {
548:         zoneCount++;
549:         if (b.level > 0) {
550:           cJobs += levelVal(d, 'jobs', b.level);
551:           powerUse += levelVal(d, 'powerUse', b.level);
552:           waterUse += levelVal(d, 'waterUse', b.level);
553:           shops++;
554:         }
555:       } else if (d.kind === 'zone-i') {
556:         zoneCount++;
557:         if (b.level > 0) {
558:           iJobs += levelVal(d, 'jobs', b.level);
559:           powerUse += levelVal(d, 'powerUse', b.level);
560:           waterUse += levelVal(d, 'waterUse', b.level);
561:           factories++;
562:           polluters.push(b);
563:         }
564:       } else {
565:         powerUse += d.powerUse || 0;
566:         waterUse += d.waterUse || 0;
567:         powerCap += d.powerSupply || 0;
568:         waterCap += d.waterSupply || 0;
569:         jobs += d.jobs || 0;
570:         if (d.powerSupply) hasPower = true;
571:         if (d.waterSupply) hasWater = true;
572:         if (artOr(defOf(b), b) === 'park' || artOr(defOf(b), b) === 'smallpark') hasPark = true;
573:         if (artOr(defOf(b), b) === 'school') hasSchool = true;
574:         if (artOr(defOf(b), b) === 'stadium') hasStadium = true;
575:       }
576:       if (d.happy && d.radius) amenities.push(b);
577:       if (b.defId === 'solar') hasPower = true;
578:     }
579:     for (let y = 0; y < state.gridSize; y++) for (let x = 0; x < state.gridSize; x++) if (state.grid[idx(x, y)].road) roadCount++;
580:     expense += roadCount * DEFS.road.maint;
581:     for (const pid in state.policies) {
582:       const p = KK.POLICIES.find(x => x.id === pid);
583:       if (p && state.policies[pid]) expense += p.cost;
584:     }
585:     workers = Math.round(pop * .42);
586:     jobs += cJobs + iJobs;
587:     const powered = powerUse <= powerCap;
588:     const watered = waterUse <= waterCap;
589:     const policyHappy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? p.happiness : 0), 0);
590:     const commerceBonus = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.commerce || 0) : 0), 0);
591:     const taxPenalty = Math.max(0, (state.taxRate || 9) - 10) * 2.5;
592:     const unemployment = workers > jobs ? Math.min(24, (workers - jobs) / Math.max(1, workers) * 30) : 0;
593:     const pollutionPolicy = KK.POLICIES.reduce((n, p) => n + (state.policies[p.id] ? (p.pollution || 0) : 0), 0);
594:     let happyTotal = 0;
595:     for (const h of houseList) {
596:       let bonus = 0;
597:       for (const a of amenities) {
598:         const ad = defOf(a);
599:         if (distance(h, a) <= (ad.radius || 0)) bonus += ad.happy || 0;
600:       }
601:       bonus = Math.min(26, bonus);
602:       let poll = 0;
603:       for (const f of polluters) {
604:         if (distance(h, f) <= (defOf(f).pollutionRadius || 3)) poll += 1.6 + f.level * .5;
605:       }
606:       poll = Math.max(0, Math.min(14, poll) - pollutionPolicy);
607:       let hv = 56 + bonus + policyHappy + state.moodBoost - taxPenalty - unemployment - poll;
608:       if (!powered) hv -= 24;
609:       if (!watered) hv -= 20;
610:       happyTotal += clamp(hv, 0, 100);
611:     }
612:     let happiness;
613:     if (houseList.length) happiness = happyTotal / houseList.length;
614:     else happiness = clamp(62 + policyHappy + state.moodBoost - taxPenalty, 0, 100);
615:     const income = pop * .33 * ((state.taxRate || 9) / 9) + cJobs * .5 * (1 + commerceBonus) + iJobs * .36;
616:     state.population = pop;
617:     state.workers = workers;
618:     state.jobs = jobs;
619:     state.commercialJobs = cJobs;
620:     state.industrialJobs = iJobs;
621:     state.powerUse = Math.round(powerUse * 10) / 10;
622:     state.powerCap = powerCap;
623:     state.waterUse = Math.round(waterUse * 10) / 10;
624:     state.waterCap = waterCap;
625:     state.powered = powered;
626:     state.watered = watered;
627:     state.expense = Math.round(expense * 10) / 10;
628:     state.income = Math.round(income * 10) / 10;
629:     state.net = Math.round((income - expense) * 10) / 10;
630:     state.happiness = Math.round(happiness);
631:     state.roadCount = roadCount;
632:     state.zoneCount = zoneCount;
633:     state.hasPower = hasPower;
634:     state.hasWater = hasWater;
635:     state.hasPark = hasPark;
636:     state.hasSchool = hasSchool;
637:     state.hasStadium = hasStadium;
638:     state.houses = houses; state.shops = shops; state.factories = factories;
639:     state.demandR = clamp(16 + jobs * 1.25 - pop * .38 + (state.happiness < 48 ? -8 : 0), 0, 100);
640:     state.demandC = clamp(8 + pop * .34 - cJobs * .85, 0, 100);
641:     state.demandI = clamp(5 + pop * .18 - iJobs * .45, 0, 100);
642:     state.maxPop = Math.max(state.maxPop, pop);
643:     // economy is deliberately forgiving: never below -2.000
644:     if (state.money < -2000) state.money = -2000;
645:     if (!state.stats) state.stats = {};
646:     state.stats.houses = houses; state.stats.shops = shops; state.stats.factories = factories;
647:   }
648:   function artOr(def, b) { return KK.render.artFor(def, b.level); }
649:   function demandFor(kind) {
650:     return kind === 'r' ? state.demandR : kind === 'c' ? state.demandC : state.demandI;
651:   }
