477:   function drawCar(ctx, car, time) {
478:     // Simulation coordinates already point to the center of the current road tile.
479:     const p = iso(car.x, car.y);
480:     const color = car.color || '#e6563d';
481:     const dir = car.dir || 'x';
482:     const dxs = dir === 'x' ? 1 : dir === '-x' ? -1 : 0;
483:     const dys = dir === 'y' ? 1 : dir === '-y' ? -1 : 0;
484:     const vx = (dxs - dys) * IX, vy = (dxs + dys) * IY;
485:     const length = Math.hypot(vx, vy) || 1;
486:     // Opposing traffic uses opposite sides of the road, leaving room to pass.
487:     const lane = 4.8;
488:     const ang = Math.atan2(vy, vx);
489:     ctx.save();
490:     ctx.translate(p.x - vy / length * lane, p.y + vx / length * lane);
491:     ctx.fillStyle = 'rgba(20,45,30,.24)';
492:     ctx.beginPath(); ctx.ellipse(0, 2, car.type === 'bus' || car.type === 'truck' ? 15 : 11, 5, ang, 0, Math.PI * 2); ctx.fill();
493:     ctx.rotate(ang + Math.PI);
494: 
495:     if (car.type === 'motorcycle') {
496:       // Compact bike with two visible wheels and a helmeted rider.
497:       ctx.fillStyle = '#26323a';
498:       ctx.beginPath(); ctx.arc(-5, 1, 2.7, 0, Math.PI * 2); ctx.fill();
499:       ctx.beginPath(); ctx.arc(5, 1, 2.7, 0, Math.PI * 2); ctx.fill();
500:       line(ctx, { x: -5, y: 1 }, { x: -1, y: -1 }, '#d8dce0', 1.4);
501:       line(ctx, { x: -1, y: -1 }, { x: 2, y: 1 }, '#d8dce0', 1.4);
502:       line(ctx, { x: 2, y: 1 }, { x: 5, y: 1 }, '#d8dce0', 1.4);
503:       ctx.fillStyle = shade(color, .72);
