38:     ctx.moveTo(pts[0].x, pts[0].y);
39:     for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i].x, pts[i].y);
40:     ctx.closePath();
41:     if (fill) { ctx.fillStyle = fill; ctx.fill(); }
42:     if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1; ctx.stroke(); }
43:   }
44:   function line(ctx, a, b, color, w, dash) {
45:     ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y);
46:     ctx.strokeStyle = color; ctx.lineWidth = w || 1;
47:     if (dash) ctx.setLineDash(dash);
48:     ctx.stroke();
49:     if (dash) ctx.setLineDash([]);
50:   }
51:   function ellipse(ctx, cx, cy, rx, ry, fill, stroke, lw) {
52:     ctx.beginPath(); ctx.ellipse(cx, cy, Math.max(rx, .1), Math.max(ry, .1), 0, 0, Math.PI * 2);
53:     if (fill) { ctx.fillStyle = fill; ctx.fill(); }
54:     if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1; ctx.stroke(); }
55:   }
56:   function roundRect(ctx, x, y, w, h, r) {
57:     const rr = Math.min(r, Math.abs(w) / 2, Math.abs(h) / 2);
58:     ctx.beginPath();
59:     ctx.moveTo(x + rr, y);
60:     ctx.arcTo(x + w, y, x + w, y + h, rr);
61:     ctx.arcTo(x + w, y + h, x, y + h, rr);
62:     ctx.arcTo(x, y + h, x, y, rr);
63:     ctx.arcTo(x, y, x + w, y, rr);
64:     ctx.closePath();
65:   }
66:   function diamondPoints(x, y, w, h, inset) {
67:     const i = inset || 0;
68:     return [iso(x + i, y + i), iso(x + w - i, y + i), iso(x + w - i, y + h - i), iso(x + i, y + h - i)];
69:   }
70:   function tileQuad(cx, cy, w, h) {
71:     // axis-aligned-ish iso quad centered on screen point
72:     return [
73:       { x: cx, y: cy - h / 2 }, { x: cx + w / 2, y: cy },
74:       { x: cx, y: cy + h / 2 }, { x: cx - w / 2, y: cy }
75:     ];
76:   }
