78:   // ---------- background ----------
79:   const clouds = [];
80:   for (let i = 0; i < 7; i++) {
81:     clouds.push({
82:       x: hash3(i, 2, 3), y: 0.08 + hash3(i, 5, 1) * .42,
83:       s: .55 + hash3(i, 7, 9) * 1.1, a: .18 + hash3(i, 1, 4) * .25,
84:       sp: .0005 + hash3(i, 8, 2) * .0012
85:     });
86:   }
87:   function drawBackground(ctx, w, h, time) {
88:     const g = ctx.createLinearGradient(0, 0, 0, h);
89:     g.addColorStop(0, '#8fd5e8');
90:     g.addColorStop(.42, '#bdeaf4');
91:     g.addColorStop(1, '#6cb8cc');
92:     ctx.fillStyle = g; ctx.fillRect(0, 0, w, h);
93:     const sun = ctx.createRadialGradient(w * .82, h * .12, 10, w * .82, h * .12, Math.max(w, h) * .55);
94:     sun.addColorStop(0, 'rgba(255,246,196,.55)');
95:     sun.addColorStop(.45, 'rgba(255,236,170,.12)');
96:     sun.addColorStop(1, 'rgba(255,236,170,0)');
97:     ctx.fillStyle = sun; ctx.fillRect(0, 0, w, h);
98:     for (const c of clouds) {
99:       const cx = ((c.x + time * c.sp) % 1.25 - .12) * w;
100:       const cy = c.y * h;
101:       const rw = 150 * c.s * (w / 1400), rh = 44 * c.s * (w / 1400);
102:       if (cy > h * .78) continue;
103:       drawCloud(ctx, cx, cy, rw, rh, c.a);
104:     }
105:   }
106:   function drawCloud(ctx, x, y, rw, rh, a) {
107:     const parts = [[0, 0, 1], [-.45, .1, .7], [.4, .12, .66], [-.15, -.22, .62], [.2, -.25, .5]];
108:     const g = ctx.createRadialGradient(x, y, 0, x, y, rw * 1.2);
109:     g.addColorStop(0, `rgba(255,255,255,${a})`);
110:     g.addColorStop(.55, `rgba(255,255,255,${a * .7})`);
111:     g.addColorStop(1, 'rgba(255,255,255,0)');
112:     ctx.fillStyle = g;
113:     ctx.beginPath();
114:     ctx.ellipse(x, y, rw * 1.1, rh * 1.7, 0, 0, Math.PI * 2);
115:     ctx.fill();
116:     for (const p of parts) {
117:       if (p[0] === 0 && p[1] === 0) continue;
118:       ctx.beginPath();
119:       ctx.ellipse(x + p[0] * rw, y + p[1] * rh, rw * .45 * p[2], rh * .8 * p[2], 0, 0, Math.PI * 2);
120:       ctx.fill();
121:     }
122:   }
