124:   // ---------- map plate ----------
125:   function drawPlate(ctx, grid) {
126:     const p = isoPts([[0, 0], [grid, 0], [grid, grid], [0, grid]]);
127:     const cx = 0, cy = grid * IY;
128:     const shadow = ctx.createRadialGradient(cx, cy + 40, 40, cx, cy + 40, grid * 42);
129:     shadow.addColorStop(0, 'rgba(3,35,42,.30)');
130:     shadow.addColorStop(.7, 'rgba(3,35,42,.10)');
131:     shadow.addColorStop(1, 'rgba(3,35,42,0)');
132:     ctx.save();
133:     ctx.translate(0, 34);
134:     ctx.scale(1.02, .88);
135:     ctx.fillStyle = shadow;
136:     ctx.beginPath(); ctx.ellipse(cx, cy, grid * 34, grid * 20, 0, 0, Math.PI * 2); ctx.fill();
137:     ctx.restore();
138:     const depth = 20;
139:     // visible cliff sides
140:     poly(ctx, [p[3], p[2], { x: p[2].x, y: p[2].y + depth }, { x: p[3].x, y: p[3].y + depth }], '#4e4032');
141:     poly(ctx, [p[2], p[1], { x: p[1].x, y: p[1].y + depth }, { x: p[2].x, y: p[2].y + depth }], '#64513e');
142:     poly(ctx, [p[3], p[0], { x: p[0].x, y: p[0].y + depth }, { x: p[3].x, y: p[3].y + depth }], '#3f3529');
143:     poly(ctx, [p[0], p[1], { x: p[1].x, y: p[1].y + depth }, { x: p[0].x, y: p[0].y + depth }], '#574636');
144:     poly(ctx, p, '#6ea758');
145:     // outer grass rim
146:     const rim = diamondPoints(0, 0, grid, grid, .1);
147:     poly(ctx, rim, '#78b45e');
148:   }
