228:   // ---------- building primitives ----------
229:   function boxGeo(x, y, w, h, inset) {
230:     const i = inset == null ? .07 : inset;
231:     return {
232:       T: iso(x + i, y + i), R: iso(x + w - i, y + i), B: iso(x + w - i, y + h - i), L: iso(x + i, y + h - i)
233:     };
234:   }
235:   function drawBox(ctx, x, y, w, h, height, opt) {
236:     const o = opt || {};
237:     const g = boxGeo(x, y, w, h, o.inset);
238:     const wall = o.wall || '#f0e3c8';
239:     const left = o.left || shade(wall, .84);
240:     const right = o.right || shade(wall, .67);
241:     const top = o.top || wall;
242:     const up = (p, dy) => ({ x: p.x, y: p.y - (dy || height) });
243:     poly(ctx, [g.L, g.B, up(g.B), up(g.L)], left);
244:     poly(ctx, [g.B, g.R, up(g.R), up(g.B)], right);
245:     poly(ctx, [up(g.T), up(g.R), up(g.B), up(g.L)], top);
246:     if (o.outline !== false) {
247:       ctx.strokeStyle = o.outlineColor || 'rgba(20,42,32,.16)';
248:       ctx.lineWidth = .8;
249:       poly(ctx, [g.L, g.B, up(g.B), up(g.L)], null, ctx.strokeStyle, .8);
250:       poly(ctx, [g.B, g.R, up(g.R), up(g.B)], null, ctx.strokeStyle, .8);
251:     }
252:     return { g, height, up, top: top };
253:   }
254:   function drawPitchedRoof(ctx, g, height, rise, color, opt) {
255:     const o = opt || {};
256:     const y = height;
257:     const T = { x: g.T.x, y: g.T.y - y }, R = { x: g.R.x, y: g.R.y - y }, B = { x: g.B.x, y: g.B.y - y }, L = { x: g.L.x, y: g.L.y - y };
258:     const cx = (T.x + B.x) / 2, cy = (T.y + B.y) / 2;
259:     const apex = { x: cx, y: cy - rise };
260:     const over = o.over || 0;
261:     if (over) {
262:       const dirs = [[T, R], [R, B], [B, L], [L, T]];
263:       for (const [a, b] of dirs) {
264:         const na = { x: a.x + (a.x - cx) * .06, y: a.y + (a.y - cy) * .06 };
265:         const nb = { x: b.x + (b.x - cx) * .06, y: b.y + (b.y - cy) * .06 };
266:         poly(ctx, [a, b, nb, na], shade(color, .7));
267:       }
268:     }
269:     poly(ctx, [L, B, apex], shade(color, .86));
270:     poly(ctx, [B, R, apex], shade(color, .66));
271:     if (o.ridge !== false) {
272:       line(ctx, apex, { x: lerp(L.x, B.x, .5), y: lerp(L.y, B.y, .5) - rise * .0 }, shade(color, .55), 1.2);
273:     }
274:     if (o.tiles) {
275:       ctx.globalAlpha = .18;
276:       for (let i = 1; i <= 3; i++) {
277:         const t = i / 4;
278:         const a = { x: lerp(L.x, B.x, t / 2), y: lerp(L.y, B.y, t / 2) };
279:         const b = { x: lerp(apex.x, B.x, t * .8), y: lerp(apex.y, B.y, t * .8) };
280:         line(ctx, { x: lerp(L.x, B.x, 1 - t), y: lerp(L.y, B.y, 1 - t) }, { x: lerp(apex.x, L.x, .5), y: lerp(apex.y, L.y, .5) }, shade(color, .5), .8);
281:       }
282:       ctx.globalAlpha = 1;
283:     }
284:   }
285:   function drawWindows(ctx, faceA, faceB, height, rows, cols, opt) {
286:     const o = opt || {};
287:     const top = o.top || 6, bottom = o.bottom || 7;
288:     const usable = height - top - bottom;
289:     if (usable < 6) return;
290:     const winH = Math.min(o.winH || 6, usable / rows * .5);
291:     const winW = o.winW || 4.6;
292:     const col = NIGHT > .28 ? '#ffd98a' : (o.color || '#bfe6f5');
293:     const frame = o.frame || 'rgba(255,255,255,.28)';
294:     const stepX = (faceB.x - faceA.x) / cols;
295:     const stepY = (faceB.y - faceA.y) / cols;
296:     for (let r = 0; r < rows; r++) {
297:       const wy = height - top - (usable / rows) * (r + .5);
298:       for (let c = 0; c < cols; c++) {
299:         const cx = faceA.x + stepX * (c + .5);
300:         const cy = faceA.y + stepY * (c + .5) - wy;
301:         const ex = (stepX / Math.abs(stepX || 1)) * winW;
302:         ctx.beginPath();
303:         ctx.moveTo(cx - ex / 2, cy);
304:         ctx.lineTo(cx + ex / 2, cy);
305:         ctx.lineTo(cx + ex / 2, cy + winH);
306:         ctx.lineTo(cx - ex / 2, cy + winH);
307:         ctx.closePath();
308:         ctx.fillStyle = col; ctx.fill();
309:         if (o.frame !== false) {
310:           ctx.strokeStyle = frame; ctx.lineWidth = .5; ctx.stroke();
311:         }
312:         if (NIGHT > .28) {
313:           ctx.globalAlpha = .18;
314:           ctx.fillStyle = '#ffe7a8';
315:           ctx.fillRect(cx - ex / 2 - 1, cy - 1, Math.abs(ex) + 2, winH + 2);
316:           ctx.globalAlpha = 1;
317:         }
318:       }
319:     }
320:   }
321:   function drawDoor(ctx, g, height, color, opt) {
322:     const o = opt || {};
323:     const frac = o.frac == null ? .5 : o.frac;
324:     const dx = lerp(g.L.x, g.B.x, frac), dy = lerp(g.L.y, g.B.y, frac);
325:     const w = o.w || 5, h = o.h || 10;
326:     poly(ctx, [
327:       { x: dx - w / 2, y: dy - h }, { x: dx + w / 2, y: dy - h },
328:       { x: dx + w / 2, y: dy }, { x: dx - w / 2, y: dy }
329:     ], color || '#7a5a3a');
330:     ctx.fillStyle = 'rgba(255,255,255,.18)';
331:     ctx.fillRect(dx + w / 2 - 1.6, dy - h / 2, 1, 1);
332:   }
333:   function drawAwning(ctx, g, height, colorA, colorB, y) {
334:     const baseY = y == null ? height - 13 : y;
335:     const segments = 6;
336:     for (let i = 0; i < segments; i++) {
337:       const t0 = i / segments, t1 = (i + 1) / segments;
338:       const a0 = { x: lerp(g.L.x, g.B.x, t0), y: lerp(g.L.y, g.B.y, t0) - baseY };
339:       const a1 = { x: lerp(g.L.x, g.B.x, t1), y: lerp(g.L.y, g.B.y, t1) - baseY };
340:       const b0 = { x: a0.x + 2, y: a0.y + 4 }, b1 = { x: a1.x + 2, y: a1.y + 4 };
341:       poly(ctx, [a0, a1, b1, b0], i % 2 ? colorB : colorA);
342:     }
343:   }
344:   function addVariantColors(b, palettes) {
345:     const idx = Math.abs(Math.floor(hash(b.x * 7 + b.uid * .17, b.y * 11 + b.level * 3) * palettes.length)) % palettes.length;
346:     return palettes[idx];
