385:       case 'shop': return drawShop(ctx, b, def, time);
386:       case 'factory': return drawFactory(ctx, b, def, time);
387:       case 'powerplant': return drawPowerPlant(ctx, b, time);
388:       case 'watertower': return drawWaterTower(ctx, b, time);
389:       case 'solar': return drawSolar(ctx, b, time);
390:       case 'police': return drawPolice(ctx, b, time);
391:       case 'fire': return drawFire(ctx, b, time);
392:       case 'school': return drawSchool(ctx, b, time);
393:       case 'hospital': return drawHospital(ctx, b, time);
394:       case 'smallpark': return drawSmallPark(ctx, b, time);
395:       case 'park': return drawPark(ctx, b, time);
396:       case 'plaza': return drawPlaza(ctx, b, time);
397:       case 'fountain': return drawFountain(ctx, b, time);
398:       case 'ferris': return drawFerris(ctx, b, time);
399:       case 'stadium': return drawStadium(ctx, b, time);
400:       case 'monument': return drawMonument(ctx, b, time);
401:       case 'tree': return drawTree(ctx, b, def, time);
402:       case 'flowers': return drawFlowers(ctx, b, time);
